#!/usr/bin/env python3
import json,sys
from pathlib import Path
G={
'医学免疫学':{'医学免疫学':'研究免疫系统组成、功能及其与疾病关系的学科。','免疫防御':'机体识别和清除病原体及其有害产物，保护机体免受感染的功能。','免疫监视':'机体识别和清除体内突变、衰老或异常细胞的功能。','免疫自稳':'免疫系统通过调节维持自身内环境稳定和免疫耐受的状态。','免疫应答':'免疫系统接受抗原刺激后，免疫细胞被活化并产生效应和记忆的过程。','半抗原':'有抗原性但通常没有免疫原性，需与载体结合后才能诱导免疫应答的小分子物质。','抗原表位':'抗原分子中能被抗体或免疫受体特异性识别和结合的局部结构。','互补决定区':'免疫球蛋白或TCR可变区中直接与抗原结合、决定特异性的高变区域。','ADCC':'抗体依赖的细胞介导的细胞毒作用，效应细胞通过抗体Fc段识别并杀伤被抗体包被的靶细胞。','单克隆抗体':'由同一B细胞克隆产生、只识别一种抗原表位的抗体。','多克隆抗体':'由多个B细胞克隆产生、可识别同一抗原多个表位的抗体。','调理作用':'抗体或补体包被病原体后，促进吞噬细胞识别、吞噬和清除的作用。','细胞因子':'由免疫细胞或其他细胞分泌、以低浓度调节免疫、炎症、造血和细胞生长的可溶性蛋白。','白细胞介素':'主要由白细胞产生并作用于白细胞或其他细胞、调节免疫和炎症反应的一类细胞因子。','趋化因子':'能诱导细胞定向迁移的一类细胞因子。','细胞因子风暴':'感染或免疫激活时多种细胞因子大量释放，造成全身炎症和组织损伤的失控状态。','主要组织相容性复合体':'编码主要组织相容性抗原、参与抗原提呈和T细胞识别的一组基因复合体。','人类白细胞抗原':'人类主要组织相容性复合体编码的抗原分子，负责向T细胞提呈抗原肽。','MHC限制性':'T细胞只有在识别抗原肽的同时识别相应MHC分子时才能被激活的特性。','B细胞抗原受体(BCR)':'表达于B细胞表面的膜型免疫球蛋白及其信号复合物，负责特异性识别抗原。','TCR':'T细胞抗原受体，通常识别由MHC分子提呈的抗原肽。','阳性选择':'胸腺内筛选能适度识别自身MHC的未成熟T细胞，使其存活并继续分化的过程。','免疫突触':'T细胞与抗原提呈细胞或靶细胞接触后形成的有序受体和黏附分子聚集界面。','Ig类别转换':'B细胞在抗原和细胞因子等信号作用下保持抗原特异性不变而改变抗体重链恒定区和类别的过程。','体细胞高频突变':'活化B细胞免疫球蛋白可变区基因发生高频点突变的过程。','抗体亲和力成熟':'免疫应答过程中B细胞经选择产生与抗原结合能力逐渐增强的抗体的过程。','初次应答':'机体首次接触某抗原后产生的免疫应答，潜伏期较长、强度较弱。','再次应答':'机体再次接触同一抗原时由记忆细胞介导的应答，反应更快、更强、持续更久。','固有免疫应答':'机体出生即具有、由屏障、吞噬细胞、NK细胞和补体等介导的快速非特异性免疫应答。','模式识别受体':'能识别病原相关模式分子或损伤相关模式分子的宿主受体。','病原相关模式分子':'病原体共有的、可被宿主模式识别受体识别的保守分子结构。','超敏反应':'机体对再次进入的抗原发生过强或异常免疫应答，导致组织损伤或功能紊乱的现象。','变应原':'能诱发过敏性超敏反应的抗原性物质。','免疫复合物':'抗原与相应抗体结合形成的复合物。','迟发型超敏反应(DTH)':'由抗原特异性T细胞和巨噬细胞等介导，通常在再次接触抗原后数十小时出现的细胞免疫反应。','人工主动免疫':'给机体接种疫苗或类毒素，使其主动产生特异性免疫和免疫记忆。','人工被动免疫':'给机体输入抗体或免疫血清，使其立即获得短期特异性保护。','类毒素':'细菌外毒素经脱毒处理后失去毒性但保留免疫原性的制剂。'},
'医学微生物学':{'MRSA':'耐甲氧西林金黄色葡萄球菌，指对甲氧西林及多数β内酰胺类抗生素耐药的金黄色葡萄球菌。','病毒体':'结构完整、具有感染性的成熟病毒颗粒。','表型混合':'两种不同病毒共同感染细胞时，子代病毒核酸与外壳来源不一致的现象。','抗原性漂移':'流感病毒表面抗原基因发生点突变导致的渐进性、小幅抗原变异。','抗原性转变':'流感病毒表面抗原发生较大幅度改变并形成新亚型的变异。','神经氨酸酶':'流感病毒包膜上的糖蛋白，参与病毒从宿主细胞释放和扩散。','机会致病菌':'在正常情况下不致病、当宿主免疫力下降或寄居部位改变时引起感染的微生物。','减毒活疫苗':'使用毒力减弱但仍能诱导免疫反应的活病原体制成的疫苗。','肉毒毒素':'肉毒梭菌产生的神经毒素，阻断神经肌肉接头乙酰胆碱释放，引起弛缓性麻痹。','巴氏消毒法':'在不破坏食品主要品质的条件下，用适度加热杀灭或减少致病菌的消毒方法。','白喉抗毒素':'含有抗白喉毒素抗体、用于中和体内游离白喉毒素的免疫制剂。'},
}
def main():
 p=Path(sys.argv[1] if len(sys.argv)>1 else 'medical_question_bank_deduplicated.json');d=json.loads(p.read_text(encoding='utf-8'));gen=orig=0
 for q in d['questions']:
  if q.get('type')!='名词解释':continue
  if q.get('answer'):
   q.setdefault('reference_answer',q['answer']);q.setdefault('answer_source','original_source');q.setdefault('answer_source_file',q.get('source'));q.setdefault('answer_source_location',q.get('source_location'));orig+=1;continue
  term=str(q.get('question','')).strip()
  if term in G.get(q.get('course'),{}):
   ans=G[q['course']][term];q['reference_answer']=ans;q['answer_source']='generated_reference';q['reference_generated']=True;q['explanation_detail']={'correct_answer_reason':ans,'plain_explanation':'这是该术语在本科医学课程中的核心含义。','option_analysis':{},'clinical_connection':'结合对应章节理解其医学意义。','exam_focus':term+'：掌握定义、作用或临床意义。','memory_points':term+'：掌握定义、作用或临床意义。','source':{'kind':'generated_reference','basis':'医学本科教材基础定义'}};gen+=1
 d.setdefault('summary',{})['term_original_answers']=orig;d['summary']['term_generated_references']=gen;d['summary']['term_needs_review']=sum(1 for q in d['questions'] if q.get('type')=='名词解释' and not q.get('reference_answer'));p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n');print('original',orig,'generated',gen,'needs',d['summary']['term_needs_review'])
if __name__=='__main__':main()
